const line_height = 22;
const btn_height = 12;

class MyMap {
    constructor() {
        this.order = [];  // 存储键的顺序
        this.data = new Map();   // 存储实际数据
        this.increment = -1;
    }
    keys() {
        return this.order;
    }
    has(key) {
        return this.data.has(key);
    }
    size() {
        return this.data.size;
    }
    set(key, value) {
        if (this.order.indexOf(key) === -1) {
            return false
        }
        this.data.set(key, value);
    }
    new(value) {
        this.increment += 1;
        this.order.push(this.increment);
        this.data.set(this.increment, value);
        return this.increment;
    }
    get(key) {
        return this.data.get(key);
    }
    last() {
        if (this.order.length == 0)
            return NaN;
        return this.order[this.order.length - 1];
    }
    swap(key1, key2) {
        const index1 = this.order.indexOf(key1);
        const index2 = this.order.indexOf(key2);
        if (index1 === -1 || index2 === -1) return false;
        [this.order[index1], this.order[index2]] =
            [this.order[index2], this.order[index1]];
        return true;
    }
    move(key, offset) {
        const currentIndex = this.order.indexOf(key);
        if (currentIndex === -1) return false;
        this.order.splice(currentIndex, 1);
        this.order.splice(currentIndex + offset, 0, key);
        return true;
    }
    delete(key) {
        const index = this.order.indexOf(key);
        if (index === -1) {
            return false;
        }
        this.order.splice(index, 1);
        this.data.delete(key);
        if (this.order.length === 0) {
            return null;
        }
        else if (index >= this.order.length) {
            return this.order[this.order.length - 1];
        }
        else {
            return this.order[index];
        }
    }
}

detail_trains = new MyMap();  // like {0: '010001', 3: '010002', ...}
detail_stations = new MyMap();  // like {0: ['惠新西街南口', '5号线', '南行'], 2: ['惠新西街南口', '5号线', '内环'], ...}
