detail_train_follow = null;
focus_detail = {
    type: '',
    train_index: NaN,
    station_index: NaN
} // for mobile, like {'type': 'train|station', 'train_index': '0', 'station_index': '1'}
detail_lines = new Array();  // like ['1号线八通线', '2号线', ...]


function change_detail(type = null) {
    if (!type)
        type = is_mobile ? 'mobile' : 'desktop';
    if (type == 'mobile') {
        is_mobile = true;
        document.getElementById('detail_broad_mobile').style.display = '';
        document.getElementById('detail_broad_desktop').style.display = 'none';
        document.getElementById('btn_detail_mobile').className = 'side-2l2-btn btn-selected';
        document.getElementById('btn_detail_desktop').className = 'side-2l2-btn btn-unselected';
        document.getElementById('btn_detail_disable').className = 'side-2l2-btn btn-unselected';
        var tag_id;
        if (focus_detail['type'] == 'train')
            tag_id = 'tag_t_' + focus_detail['train_index'];
        else if (focus_detail['type'] == 'station')
            tag_id = 'tag_s_' + focus_detail['station_index'];
        if (document.getElementById(tag_id)) {
            document.getElementById('detail_mobile').appendChild(document.getElementById(tag_id));
        }
        else if (detail_trains.size() > 0) {
            focus_detail['type'] = 'train';
            focus_detail['train_index'] = detail_trains.last();
            focus_detail['station_index'] = detail_stations.last();
            switch_detail_mobile('train', focus_detail['train_index']);
        }
        else if (detail_stations.size() > 0) {
            focus_detail['type'] = 'station';
            focus_detail['train_index'] = detail_trains.last();
            focus_detail['station_index'] = detail_stations.last();
            switch_detail_mobile('station', focus_detail['station_index']);
        }
        else {
            focus_detail['type'] = '';
            focus_detail['train_index'] = detail_trains.last();
            focus_detail['station_index'] = detail_stations.last();
            document.getElementById('detail_mobile_instructions').style.display = '';
            switch_detail_mobile_header('none');
        }
        for (let tag of document.getElementById('detail_desktop_train').children)
            document.getElementById('detail_mobile_hidden').appendChild(tag);
        for (let tag of document.getElementById('detail_desktop_station').children)
            document.getElementById('detail_mobile_hidden').appendChild(tag);
        update_detail_tag();
    }
    else if (type == 'desktop') {
        is_mobile = false;
        document.getElementById('detail_broad_mobile').style.display = 'none';
        document.getElementById('detail_broad_desktop').style.display = '';
        document.getElementById('btn_detail_mobile').className = 'side-2l2-btn btn-unselected';
        document.getElementById('btn_detail_desktop').className = 'side-2l2-btn btn-selected';
        document.getElementById('btn_detail_disable').className = 'side-2l2-btn btn-unselected';
        for (let train_index of detail_trains.keys()) {
            let tag_id = 'tag_t_' + train_index;
            document.getElementById('detail_desktop_train').appendChild(document.getElementById(tag_id));
        }
        for (let station_index of detail_stations.keys()) {
            let tag_id = 'tag_s_' + station_index;
            document.getElementById('detail_desktop_station').appendChild(document.getElementById(tag_id));
        }
        update_detail_tag();
    }
    else {
        document.getElementById('detail_broad_mobile').style.display = 'none';
        document.getElementById('detail_broad_desktop').style.display = 'none';
        document.getElementById('btn_detail_mobile').className = 'side-2l2-btn btn-unselected';
        document.getElementById('btn_detail_desktop').className = 'side-2l2-btn btn-unselected';
        document.getElementById('btn_detail_disable').className = 'side-2l2-btn btn-selected';
    }
}

function display_detail() {
    if (is_mobile) {
        switch_detail_mobile_header();
        if (parseFloat(document.getElementById('detail_broad_mobile').style.height) > 0) return;
        document.getElementById('detail_mobile_button_c').children[0].style.transform = 'rotate(180deg)';
        document.getElementById('detail_broad_mobile').style.height = '198px';
        document.getElementById('detail_mobile_button_c').setAttribute('onclick', 'hide_detail()')
    }
    else {
        if (parseFloat(document.getElementById('detail_broad_desktop').style.right) == 0) return;
        document.getElementById('detail_desktop_button_c').children[0].style.transform = 'rotate(90deg)';
        document.getElementById('detail_broad_desktop').style.right = '0px';
        document.getElementById('detail_desktop_button_c').setAttribute('onclick', 'hide_detail()')
    }
}

function hide_detail() {
    if (is_mobile) {
        switch_detail_mobile_header('none');
        document.getElementById('detail_mobile_button_c').children[0].style.transform = 'rotate(0deg)';
        document.getElementById('detail_broad_mobile').style.height = '0px';
        document.getElementById('detail_mobile_button_c').setAttribute('onclick', 'display_detail()')
    }
    else {
        if (parseFloat(document.getElementById('detail_broad_desktop').style.right) != 0) return;
        document.getElementById('detail_desktop_button_c').children[0].style.transform = 'rotate(270deg)';
        document.getElementById('detail_broad_desktop').style.right = '-320px';
        document.getElementById('detail_desktop_button_c').setAttribute('onclick', 'display_detail()')
    }
}

function switch_detail_mobile_header(type) {
    if (!type) type = focus_detail['type'];
    if (type == 'train') {
        focus_detail['type'] = 'train';
        document.getElementById('detail_mobile_instructions').style.display = 'none';
        document.getElementById('detail_mobile_button_l').style.backgroundColor = '#e5e5e5';
        document.getElementById('detail_mobile_button_r').style.backgroundColor = '#bbbbbb';
    }
    else if (type == 'station') {
        focus_detail['type'] = 'station';
        document.getElementById('detail_mobile_instructions').style.display = 'none';
        document.getElementById('detail_mobile_button_r').style.backgroundColor = '#e5e5e5';
        document.getElementById('detail_mobile_button_l').style.backgroundColor = '#bbbbbb';
    }
    else {
        //document.getElementById('detail_mobile_instructions').style.display = '';
        document.getElementById('detail_mobile_button_l').style.backgroundColor = '#bbbbbb';
        document.getElementById('detail_mobile_button_r').style.backgroundColor = '#bbbbbb';
    }
}

function switch_detail_mobile(type, index = NaN) {
    display_detail();
    var target_tag_id;
    if (type == 'train') {
        if (isNaN(index)) index = focus_detail['train_index'];
        if (isNaN(index)) index = detail_trains.last();
        if (!detail_trains.has(index)) {
            //new_detail_train();
            return;
        }
        switch_detail_mobile_header('train');
        focus_detail['train_index'] = index;
        target_tag_id = 'tag_t_' + index;
    }
    else if (type == 'station') {
        if (isNaN(index)) index = focus_detail['station_index'];
        if (isNaN(index)) index = detail_stations.last();
        if (!detail_stations.has(index)) {
            //new_detail_station();
            return;
        }
        switch_detail_mobile_header('station');
        focus_detail['station_index'] = index;
        target_tag_id = 'tag_s_' + index;
    }
    var now_tag_id = document.getElementById('detail_mobile').firstChild?.id;
    if (now_tag_id == target_tag_id) return;
    if (document.getElementById('detail_mobile').firstChild) {
        document.getElementById('detail_mobile_hidden').appendChild(document.getElementById('detail_mobile').firstChild);
    }
    document.getElementById('detail_mobile').appendChild(document.getElementById(target_tag_id));
}

function move_detail_tag(type, index, offset) {
    if (type == 'train') {
        detail_trains.move(index, offset);
        tag_id = 'tag_t_' + index;
    }
    else if (type == 'station') {
        detail_stations.move(index, offset);
        tag_id = 'tag_s_' + index;
    }
    if (!is_mobile) {
        move_div(tag_id, offset);
    }
    update_detail_tag();
}

function move_div(tag_id, offset) {
    var tag = document.getElementById(tag_id);
    var parent_tag = tag.parentNode;
    var length = parent_tag.children.length;
    if (length <= 1) return;
    var current_index = Array.from(parent_tag.children).indexOf(tag);
    if (offset > 0) offset += 1;
    var new_index = current_index + offset;
    if (new_index > length) new_index = length;
    if (new_index < 0) new_index = 0;

    if (new_index == length) {
        parent_tag.appendChild(tag);
    }
    else {
        parent_tag.insertBefore(
            tag,
            parent_tag.children[new_index]
        );
    }
}

function update_detail_tag() {
    if (is_mobile) {
        document.getElementById('detail_mobile_train_count').innerText = detail_trains.size();
        document.getElementById('detail_mobile_station_count').innerText = detail_stations.size();
    }
    else {
        document.getElementById('detail_desktop_train_count').innerText = detail_trains.size();
        document.getElementById('detail_desktop_station_count').innerText = detail_stations.size();
    }
    var indexs = detail_trains.keys();
    for (let i = 0; i < indexs.length; i++) {
        let index = indexs[i];
        let tag = document.getElementById('tag_t_' + index);
        let btn_up = tag.querySelectorAll('[data-id="up"]')[0];
        let btn_down = tag.querySelectorAll('[data-id="down"]')[0];
        if (i == 0) {
            btn_up.className = 'btn-forbidden';
            btn_up.setAttribute('onclick', '');
        }
        else {
            btn_up.className = 'btn-unselected';
            if (is_mobile)
                btn_up.setAttribute('onclick', `switch_detail_mobile('train', ${indexs[i - 1]});`);
            else
                btn_up.setAttribute('onclick', `move_detail_tag('train', ${indexs[i]}, -1);`);
        }
        if (i == indexs.length - 1) {
            btn_down.className = 'btn-forbidden';
            btn_down.setAttribute('onclick', '');
        }
        else {
            btn_down.className = 'btn-unselected';
            if (is_mobile)
                btn_down.setAttribute('onclick', `switch_detail_mobile('train', ${indexs[i + 1]});`);
            else
                btn_down.setAttribute('onclick', `move_detail_tag('train', ${indexs[i]}, 1);`);
        }
    }
    var indexs = detail_stations.keys();
    for (let i = 0; i < indexs.length; i++) {
        let index = indexs[i];
        let tag = document.getElementById('tag_s_' + index);
        let btn_up = tag.querySelectorAll('[data-id="up"]')[0];
        let btn_down = tag.querySelectorAll('[data-id="down"]')[0];
        if (i == 0) {
            btn_up.className = 'btn-forbidden';
            btn_up.setAttribute('onclick', '');
        }
        else {
            btn_up.className = 'btn-unselected';
            if (is_mobile)
                btn_up.setAttribute('onclick', `switch_detail_mobile('station', ${indexs[i - 1]});`);
            else
                btn_up.setAttribute('onclick', `move_detail_tag('station', ${indexs[i]}, -1);`);
        }
        if (i == indexs.length - 1) {
            btn_down.className = 'btn-forbidden';
            btn_down.setAttribute('onclick', '');
        }
        else {
            btn_down.className = 'btn-unselected';
            if (is_mobile)
                btn_down.setAttribute('onclick', `switch_detail_mobile('station', ${indexs[i + 1]});`);
            else
                btn_down.setAttribute('onclick', `move_detail_tag('station', ${indexs[i]}, 1);`);
        }
    }
}

function add_detail_train(train_id, targe_time = null) {
    display_detail();
    if (is_mobile) {
        switch_detail_mobile_header('train');
    }
    else {
        document.getElementById('detail_desktop_train_instructions').style.display = 'none';
    }
    var index = detail_trains.new(train_id)
    var tag_id = 'tag_t_' + index;
    detail_scroll.push(tag_id);
    //focus_detail = { 'type': 'train', 'index': index };
    //focus_detail['type'] = 'train';
    focus_detail['train_index'] = index;
    var new_div = document.createElement('div');
    //var tag_id = train_id + '_detail_train';
    new_div.id = tag_id;
    new_div.className = 'detail-tag';
    if (is_mobile) {
        if (document.getElementById('detail_mobile').firstChild)
            document.getElementById('detail_mobile_hidden').appendChild(document.getElementById('detail_mobile').firstChild);
        document.getElementById('detail_mobile').appendChild(new_div);
    }
    else {
        document.getElementById('detail_desktop_train').appendChild(new_div);
    }
    set_detail_train(index, targe_time);
}

function set_detail_train(index, targe_time = null) {
    var train_id = detail_trains.get(index);
    var tag_id = 'tag_t_' + index;
    var tag = document.getElementById(tag_id);
    var temp = sche_trains_wde[wde][train_id];
    var line_name = temp['line'];
    var line_direct = temp['direct'];
    var line_wde = temp['wde'];
    var line_stations = temp['stations'];
    var line_color = line_colors[line_name];
    var html = `
        <div class="detail-content">
            <div class="detail-content-l">
                <div class="detail-text">虚拟车号: ${train_id}</div>
                <div class="detail-text">演示时间: <a data-id="running_time">--:--:--</a></div>
                <div class="detail-text">已过/全程站数: <a data-id="count_passed">-</a>/<a data-id="count_total">${line_stations.length}</a></div>
            </div>
            <div class="detail-content-r">
                <div class="detail-linename" style="background-color: ${line_color};">${line_name}</div>
                <div class="detail-text">${line_direct} (${line_wde == 'wd' ? '工作日' : '双休日'})</div>
            </div>
            <div class="detail-content-button">
                <div></div>
                <div class="btn-forbidden" data-id="locate" onclick="locate_train(event, '${train_id}')"><i class="iconfont icon-map-marker"></i></div>
                <div class="btn-selected" data-id="scroll" onclick="change_table_scroll('${tag_id}')"><i class="iconfont icon-format-indent-increase"></i></div>
                <div class="btn-unselected" data-id="close" onclick="close_detail_train(${index})"><i class="iconfont icon-close"></i></div>
                <div class="btn-unselected" data-id="up"><i class="iconfont icon-menu-up"></i></div>
                <div class="btn-unselected" data-id="down"><i class="iconfont icon-menu-down"></i></div>
            </div>
        </div>
        <div class="detail-block-parent">
            <div class="detail-block">
    `;
    var is_wait = false;
    for (let i = 0; i < line_stations.length; i++) {
        var station_type;
        var time = line_stations[i][1];
        var station_name = line_stations[i][0];
        if (is_wait) {
            is_wait = false;
            station_type = '发车';
        }
        else if (time[0] == '(') {
            station_type = '越行';
            time = time.slice(1);
        }
        else if (time[time.length - 1] == '-') {
            station_type = '待避';
            time = time.slice(0, -1);
            is_wait = true;
        }
        else if (close_stations[line_name] && close_stations[line_name][station_name]) station_type = close_stations[line_name][station_name];
        else if (i == 0) station_type = '始发';
        else if (i == line_stations.length - 1) station_type = '终到';
        else station_type = '经停';

        var use_station, station_description = '';
        if (transfer_without_exiting_stations[line_name] && transfer_without_exiting_stations[line_name].indexOf(station_name) != -1) {
            use_station = '<use href="#detail_v_transfer_station_dash" />';
            station_description = '虚拟换乘';
        }
        else if (ex_stations_lines[station_name] && ex_stations_lines[station_name].indexOf(line_name) != -1) {
            use_station = '<use href="#detail_v_transfer_station" />';
            station_description = '换乘车站';
        }
        else if (close_stations[line_name] && close_stations[line_name][station_name])
            use_station = '<use href="#detail_v_station_dash" />';
        else
            use_station = '<use href="#detail_v_station" />';
        var this_html = `
            <div>
                <div>
                    <svg xmlns="http://www.w3.org/2000/svg" width="22px" height="22px">
                        ${i > 0 ? '<use href="#detail_v_line_up" class="detail-v-line"/>' : ''}
                        ${i < line_stations.length - 1 ? '<use href="#detail_v_line_down" class="detail-v-line"/>' : ''}
                        ${use_station}
                    </svg>
                </div>
                <div>${i + 1}</div>
                <div>${time}</div>
                <div>${station_type}</div>
                <div>${station_name}</div>
                <div>${station_description}</div>
                <div onclick="add_detail_station('${station_name}','${line_name}', '${line_direct}', '${time}')"><i class="iconfont icon-open-in-new"></i></div>
            </div>
        `;
        if (i == 0) {
            this_html = `<div class="detail-table detail-table-train" data-id="table"><div class="detail-table-first">` + this_html + `</div><div class="detail-table-scroll" data-id="table_scroll" goingto="2">`;
        }
        else if (i == line_stations.length - 1) {
            this_html = '</div><div class="detail-table-last">' + this_html + '</div></div>';
        }
        html += this_html;
    }
    html += `
        <div class="custom-scrollbar">
            <div class="scroll-btn" onclick="change_table_scroll('${tag_id}', true);table_scroll_to('${tag_id}', NaN, -1);">
                <i class="iconfont icon-menu-up"></i>
            </div>
            <div class="scroll-bar" data-id="scroll_bar">
                <div class="scroll-thumb" data-id="scroll_thumb"></div>
            </div>
            <div class="scroll-btn scroll-down" onclick="change_table_scroll('${tag_id}', true);table_scroll_to('${tag_id}', NaN, 1);">
                <i class="iconfont icon-menu-down"></i>
            </div>
        </div>
    `
    html += '</div></div>';
    tag.innerHTML = html;
    update_scroll_thumb(tag_id);
    //if (!isNaN(train_station_index)) {
    //    change_table_scroll(train_id, is_move = false);
    //    table_scroll_to(train_id, train_station_index);
    //}
    tag.querySelectorAll('[data-id="table_scroll"]')[0].addEventListener('wheel', ban_event);
    tag.querySelectorAll('[data-id="table"]')[0].addEventListener('wheel', on_table_wheel);
    tag.querySelectorAll('[data-id="table_scroll"]')[0].addEventListener('touchmove', on_table_touch_move);
    //tag.querySelectorAll('[data-id="scroll_thumb"]')[0].addEventListener('touchstart', ban_event);
    //tag.querySelectorAll('[data-id="scroll_thumb"]')[0].addEventListener('mousedown', ban_event);
    tag.querySelectorAll('[data-id="scroll_thumb"]')[0].addEventListener('touchstart', on_scroll_thumb_start);
    tag.querySelectorAll('[data-id="scroll_thumb"]')[0].addEventListener('mousedown', on_scroll_thumb_start);
    //tag.querySelectorAll('[data-id="scroll_bar"]')[0].addEventListener('touchstart', ban_event);
    //tag.querySelectorAll('[data-id="scroll_bar"]')[0].addEventListener('mousedown', ban_event);
    //tag.querySelectorAll('[data-id="scroll_bar"]')[0].addEventListener('touchstart', on_scroll_bar_down);
    tag.querySelectorAll('[data-id="scroll_bar"]')[0].addEventListener('mousedown', on_scroll_bar_down);
    tag.querySelectorAll('[data-id="table_scroll"]')[0].addEventListener('scroll', on_table_scroll);
    if (targe_time === null)
        update_detail_train(index, true, true);
    else {
        update_detail_train(index, true, false);
        change_table_scroll(tag_id, true);
        for (var i = 0; i < line_stations.length; i++) {
            if (hm2time(line_stations[i][1]) > hm2time(targe_time)) break;
        }
        table_scroll_to(tag_id, i, NaN, false);
    }
    update_detail_tag();
}

